// The runtime treats a camouflage suit as the receipts do (the netting lane, 2026-10-11, the coordinator's condition on
// leaving camouflage out of the physical-geometry receipts, camouflageBounds.test-support.mjs):
// 1. no shell meets the net: hits resolve on the simulation's armour model (sim/armor.ts traceTank over spec.armor,
//    generated by tools/gen-combat-anatomy.mjs from the named armour buckets), and no simulation module touches the
//    scene graph; the one combat path that rays the rendered vehicle, the impact scar's skin clamp
//    (fx/impactDecals.ts), passes through the suit to the armour under it;
// 2. no gameplay shape comes from suited bounds: body contact reads the generated hull shell (sim/tankContactShape.ts),
//    the suit is nonArmor decor that no hit-geometry builder takes, and nothing at runtime bounds a suited root
//    (Box3.setFromObject runs on fittings, galleries and the suit's own cap only);
// 3. the suit never pops: each mesh is culled by its own geometry's bounds (left for the renderer to compute from the
//    finished buffer, or holding every vertex), under no LOD level and in no distance-detail set, in the garage
//    build and in a battle bot's;
// and, from the fix round, a near hull casts the suit's shadow with its armour (nearVehicleShadowDetail.ts).
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import * as THREE from 'three';
import { createTank } from './tankFactory.ts';
import { getSpec } from './specs.ts';
import { ensureInteriorFills } from './interiorFills.ts';
import { isCombatVisibleObject } from './combatVisibility.ts';
import { isImpactDecalSkin } from '../fx/impactDecals.ts';
import { vehicleShadowDetailOf } from '../engine/nearVehicleShadowDetail.ts';
import { createTankState } from '../sim/movement.ts';
import { installCanvasFixture } from './canvasFixture.test-support.mjs';
import { notCamouflage } from './camouflageBounds.test-support.mjs';

// 1/2: the simulation never reads the scene graph, so the suit cannot reach a trace, a contact or a hit box
const simDir = new URL('../sim/', import.meta.url);
for (const file of readdirSync(simDir)) {
  if (!file.endsWith('.ts') || file.includes('.selftest.')) continue;
  const text = readFileSync(new URL(file, simDir), 'utf8');
  assert.doesNotMatch(text, /Raycaster|intersectObjects?\(|setFromObject|expandByObject|\.traverse\(|getObjectByName|Object3D/,
    `sim/${file} stays on armour data, off the scene graph`);
}

const restoreCanvas = installCanvasFixture();
// a woodland field net with a turret roof and an open-mount hull with a drape; the garage build and a desktop bot's
const IDS = ['t90a_burlak', 'griffin_viper'];
const BUILDS = {
  garage: { quality: 'high' },
  bot: { quality: 'high', geometryQuality: 'low', batchStatic: true, battleDetailLod: true, eraVisualBindingReceipt: false },
};
const shown = (object, root) => {
  for (let node = object; node; node = node.parent) {
    if (!node.visible) return false;
    if (node === root) return true;
  }
  return false;
};
await ensureInteriorFills(IDS);
let meshes = 0;
for (const id of IDS) {
  for (const [build, options] of Object.entries(BUILDS)) {
    const tank = createTank(id, null, { proceduralOnly: true, camoSeed: 4242, ...options });
    try {
      tank.root.updateMatrixWorld(true);
      const suit = [];
      tank.root.traverse((o) => { if (o.isMesh && /_ghillie_/.test(o.name)) suit.push(o); });
      assert.ok(suit.length >= 4, `${id} ${build}: the field suit is built (hull and turret, net and garnish)`);
      const armour = tank.root.getObjectByName('hull');
      assert.ok(armour?.isMesh, `${id} ${build}: the hull armour is built`);
      assert.equal(isImpactDecalSkin(tank.root, armour), true, `${id} ${build}: the armour under the suit takes the scar`);
      const casters = new Set(vehicleShadowDetailOf(tank.root)?.detail ?? []);
      for (const mesh of suit) {
        const label = `${mesh.name} (${build})`;
        // the receipts' guard holds on every suit mesh (it throws otherwise): nonArmor open-lattice, alpha-tested maps
        assert.equal(notCamouflage(mesh), false, `${label} leaves the physical-geometry receipts`);
        // 1: the impact scar passes through it to the armour
        assert.equal(isImpactDecalSkin(tank.root, mesh), false, `${label}: no impact scar lands on the suit`);
        // 2: never armour, external armour or equipment
        assert.equal(mesh.userData.combatHitboxRole, 'nonArmor', `${label} is nonArmor decor`);
        assert.equal(isCombatVisibleObject(mesh), false, `${label} is no combat stock`);
        // 3: culled by its own bounds, which hold every vertex
        assert.equal(mesh.frustumCulled, true, `${label} is frustum culled by its own bounds`);
        const geometry = mesh.geometry, sphere = geometry.boundingSphere;
        if (sphere) {
          const v = new THREE.Vector3(), position = geometry.attributes.position;
          for (let i = 0; i < position.count; i++) {
            assert.ok(v.fromBufferAttribute(position, i).distanceTo(sphere.center) <= sphere.radius + 1e-5,
              `${label}: its bounds hold vertex ${i}`);
          }
        }
        // 3: under no LOD level and in no detachable detail group
        for (let p = mesh.parent; p && p !== tank.root; p = p.parent) {
          assert.ok(!p.isLOD, `${label} hangs under no LOD level`);
          assert.ok(!p.userData.battleDetailGroup, `${label} is in no battle detail group`);
        }
        // the fix round: a near hull casts it
        assert.ok(casters.has(mesh), `${label} casts with the near hull's armour`);
        meshes++;
      }
      if (build === 'bot') {
        // 3: a battle bot keeps the suit at every distance (the detail policies hand off at 52-122 m)
        const state = createTankState(getSpec(id), new THREE.Vector3(), 0);
        for (const distance of [150, 30, 400]) {
          tank.syncFromState(state, 0, distance);
          for (const mesh of suit) assert.ok(shown(mesh, tank.root), `${mesh.name} (bot) is drawn at ${distance} m`);
        }
      }
    } finally {
      tank.dispose();
    }
  }
}
restoreCanvas();
console.log(`camouflageRuntime: ${meshes} suit meshes on ${IDS.length} hulls (garage and bot builds): no scar, hit shape, LOD`
  + ' or detail hand-off takes the suit; its own bounds cull it; near hulls cast it');
